def weekly_times_to_slots(apps, schema_editor):
    """Each old session (one weekday, one time) becomes one weekly slot; old in-session records get the
    start of the meeting they were counted for, so per-meeting stats keep working for past data."""
    Session = apps.get_model("attendance", "Session")
    SessionSlot = apps.get_model("attendance", "SessionSlot")
    Record = apps.get_model("attendance", "AttendanceRecord")
    for s in Session.objects.all():
        SessionSlot.objects.create(session=s, days=[s.weekday], start_time=s.start_time, end_time=s.end_time)
    for r in Record.objects.filter(in_session=True, session__isnull=False).select_related("session"):
        day = timezone.localdate(r.timestamp)
        r.occurrence_start = timezone.make_aware(datetime.combine(day, r.session.start_time))
        r.save(update_fields=["occurrence_start"])


def slots_to_weekly_times(apps, schema_editor):
    """Rollback: each session keeps only its first weekly slot (one-off dates cannot be represented)."""
    Session = apps.get_model("attendance", "Session")
    for s in Session.objects.all():
        slot = next((x for x in s.slots.order_by("start_time", "id") if x.days), None)
        s.weekday = min(slot.days) if slot else 0
        s.start_time = slot.start_time if slot else time(0)
        s.end_time = slot.end_time if slot else time(0, 1)
        s.save(update_fields=["weekday", "start_time", "end_time"])


